// Layer 1 — Uomd.Narrative: Voice-synchronized punctuation-aware subtitle reveal engine
// (1:1 C# port of apps/game/src/ui/subtitles.ts).

using System;
using System.Collections.Generic;
using UnityEngine;

namespace Uomd.Narrative
{
    public struct SubtitleWordTiming
    {
        public string word;
        public float startSeconds;
        public float endSeconds;
    }

    public sealed class SubtitleSynchronizer
    {
        private readonly List<SubtitleWordTiming> _timings = new List<SubtitleWordTiming>();
        private string _fullText = "";
        private float _totalDuration = 1.5f;
        private float _elapsed;
        private bool _reducedMotion;

        public string FullText => _fullText;
        public float TotalDuration => _totalDuration;
        public bool IsComplete => _reducedMotion || _elapsed >= _totalDuration;

        public void BeginLine(string text, float voiceDurationSeconds, bool reducedMotion)
        {
            _fullText = text ?? "";
            _reducedMotion = reducedMotion;
            _elapsed = 0f;
            _timings.Clear();

            if (string.IsNullOrWhiteSpace(_fullText))
            {
                _totalDuration = 0.01f;
                return;
            }

            string[] words = _fullText.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
            float estimatedDuration = voiceDurationSeconds > 0.25f
                ? voiceDurationSeconds
                : Mathf.Clamp(words.Length * 0.24f, 1.1f, 8.5f);

            _totalDuration = estimatedDuration;

            float totalWeight = 0f;
            float[] weights = new float[words.Length];
            for (int i = 0; i < words.Length; i++)
            {
                string w = words[i];
                float weight = Mathf.Max(1f, w.Length * 0.18f);
                if (w.EndsWith(".", StringComparison.Ordinal) || w.EndsWith("!", StringComparison.Ordinal) || w.EndsWith("?", StringComparison.Ordinal))
                {
                    weight += 1.35f;
                }
                else if (w.EndsWith(",", StringComparison.Ordinal) || w.EndsWith(";", StringComparison.Ordinal) || w.EndsWith(":", StringComparison.Ordinal) || w.EndsWith("—", StringComparison.Ordinal))
                {
                    weight += 0.75f;
                }
                weights[i] = weight;
                totalWeight += weight;
            }

            float cursor = 0f;
            for (int i = 0; i < words.Length; i++)
            {
                float slice = (weights[i] / Mathf.Max(0.01f, totalWeight)) * _totalDuration;
                _timings.Add(new SubtitleWordTiming
                {
                    word = words[i],
                    startSeconds = cursor,
                    endSeconds = cursor + slice
                });
                cursor += slice;
            }
        }

        public string Tick(float deltaSeconds, float timeScale = 1f)
        {
            if (_reducedMotion || _timings.Count == 0)
            {
                _elapsed = _totalDuration;
                return _fullText;
            }

            _elapsed += Mathf.Max(0f, deltaSeconds) * Mathf.Max(0.1f, timeScale);
            if (_elapsed >= _totalDuration)
            {
                return _fullText;
            }

            int visibleCount = 0;
            for (int i = 0; i < _timings.Count; i++)
            {
                if (_elapsed >= _timings[i].startSeconds)
                {
                    visibleCount = i + 1;
                }
                else
                {
                    break;
                }
            }

            if (visibleCount <= 0) return "";
            if (visibleCount >= _timings.Count) return _fullText;

            var sb = new System.Text.StringBuilder();
            for (int i = 0; i < visibleCount; i++)
            {
                if (i > 0) sb.Append(' ');
                sb.Append(_timings[i].word);
            }
            return sb.ToString();
        }

        public void RevealImmediately()
        {
            _elapsed = _totalDuration;
        }
    }
}
